{"query": "PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?name WHERE {
  ?t a :Trial ; :phase ?p ; :condition ?c ; :testsDrug ?d .
  FILTER(?p IN ("PHASE3", "PHASE2/PHASE3"))
  ?c :within ?m . ?m rdfs:label "Breast Neoplasms"@en .
  ?d :hasTarget ?tg ; :name ?name .
  ?tg :gene "ERBB2" .
}"}
